    pontos:[ { ico:"💬", t:"Explícita, clara e congruente", d:"requisitos da motivação" }, { ico:"🤝", t:"Concordância", d:"a autoridade pode adotar fundamentos anteriores" }, { ico:"📑", t:"Pareceres e decisões", d:"fontes admitidas" }, { ico:"🧩", t:"Parte do ato", d:"os fundamentos passam a integrá-lo" } ],
