    regra:"Sujeito ativo é o {0|agente público} (art. 2º), mas a Lei também se aplica a quem {1|não é agente público} e {2|induz ou concorre dolosamente} (art. 3º).",
    pontos:[ { ico:"🏛️", t:"Agente público", d:"sujeito típico" }, { ico:"👤", t:"Não agente público", d:"também pode ser alcançado" }, { ico:"🧠", t:"Induz ou concorre", d:"sempre com dolo" } ],
